#include <cstddef>

class Buffer
{
public:
    explicit Buffer(std::size_t size) : m_data{ new int[size]{} }, m_size{ size } {}
    ~Buffer() { delete[] m_data; }
    Buffer(const Buffer& other) : m_data{ new int[other.m_size] }, m_size{ other.m_size }
    {
        for (std::size_t i{ 0 }; i < m_size; ++i) m_data[i] = other.m_data[i];
    }

    Buffer& operator=(const Buffer& other)
    {
        if (this == &other)
        {
            return *this;
        }
        int* fresh{ new int[other.m_size] };
        for (std::size_t i{ 0 }; i < other.m_size; ++i)
        {
            fresh[i] = other.m_data[i];
        }
        delete[] m_data;
        m_data = fresh;
        m_size = other.m_size;
        return *this;
    }

    int& operator[](std::size_t i) { return m_data[i]; }
    const int& operator[](std::size_t i) const { return m_data[i]; }
    std::size_t size() const { return m_size; }
    const int* data() const { return m_data; }

private:
    int* m_data{ nullptr };
    std::size_t m_size{ 0 };
};

unitTests:
TEST("assignment copies contents and size") { Buffer a{ 3 }; a[1] = 7; Buffer b{ 10 }; b = a; CHECK_EQ(b.size(), 3u); CHECK_EQ(b[1], 7); CHECK(a.data() != b.data()); }
TEST("the two stay independent") { Buffer a{ 2 }; Buffer b{ 2 }; b = a; b[0] = 5; CHECK_EQ(a[0], 0); }
TEST("self-assignment is harmless") { Buffer a{ 2 }; a[0] = 4; Buffer& same{ a }; a = same; CHECK_EQ(a[0], 4); CHECK_EQ(a.size(), 2u); }
TEST("assignment can be chained") { Buffer a{ 1 }; a[0] = 3; Buffer b{ 1 }, c{ 1 }; c = b = a; CHECK_EQ(c[0], 3); }
TEST("the old array is freed") { CHECK_NO_LEAK(Buffer a{ 100 }; Buffer b{ 200 }; b = a; a = b); }

